<body>
    <header>
        <h1>MapleSure SponsorConnect</h1>
    </header>
    <div class="container">
        <form id="claim-form">
            <div class="form-group">
                <label for="policy-number">Policy Number</label>
                <input type="text" id="policy-number" name="policy-number">
            </div>
            <div class="form-group">
                <label for="member-id">Member ID</label>
                <input type="text" id="member-id" name="member-id">
            </div>
            <button type="button" onclick="lookUpMember()">Look up member</button>
            <div id="member-details" class="form-group" style="display:none;">
                <p><strong>Member Details:</strong> John Doe, Premium Member</p>
            </div>
            <div class="form-group">
                <label for="last-day-worked">Last Day Worked</label>
                <input type="date" id="last-day-worked" name="last-day-worked">
            </div>
            <div class="form-group">
                <label for="first-day-absent">First Day Absent</label>
                <input type="date" id="first-day-absent" name="first-day-absent">
            </div>
            <div class="form-group">
                <label for="nature-of-absence">Nature of Absence</label>
                <select id="nature-of-absence" name="nature-of-absence">
                    <option value="sick">Sick</option>
                    <option value="injury">Injury</option>
                    <option value="maternity">Maternity</option>
                </select>
            </div>
            <div class="form-group">
                <label for="details">Details</label>
                <textarea id="details" name="details" rows="4"></textarea>
            </div>
            <div class="form-group">
                <label for="documents">Upload Documents</label>
                <input type="file" id="documents" name="documents" multiple onchange="displayFileNames()">
                <ul id="file-list"></ul>
            </div>
            <div class="form-group">
                <button type="submit">Submit Claim</button>
            </div>
        </form>
        <div id="confirmation">
