        <p>MapleSure Insurance — fictional demo application</p>
    </footer>
    <script>
        const mockData = {
            "12345": { "memberId": "98765", "details": "John Doe, Premium Member" }
        };

        function lookUpMember() {
            const policyNumber = document.getElementById('policy-number').value;
            const memberId = document.getElementById('member-id').value;
            const memberDetails = document.getElementById('member-details');

            if (mockData[policyNumber] && mockData[policyNumber].memberId === memberId) {
                memberDetails.style.display = 'block';
            } else {
                memberDetails.style.display = 'none';
                alert('Member not found');
            }
        }

        function displayFileNames() {
            const files = document.getElementById('documents').files;
            const fileList = document.getElementById('file-list');
            fileList.innerHTML = '';
            for (let i = 0; i < files.length; i++) {
                const li = document.createElement('li');
                li.textContent = files[i].name;
                fileList.appendChild(li);
            }
        }

        document.getElementById('claim-form').onsubmit = function(event) {
            event.preventDefault();
            const confirmation = document.getElementById('confirmation');
            const claimForm = document.getElementById('claim-form');
            const referenceNumber = document.getElementById('reference-number');
            const randSuffix = Math.floor(1000 + Math.random() * 9000);
            referenceNumber.textContent = `MS-2026-08-${randSuffix}`;
            claimForm.style.display = 'none';
            confirmation.style.display = 'block';
        };
    </script>
</body>
